96	// decodeRegisterRequest parses the registration body token by token so the
97	// field whitelist stays case-sensitive and duplicate keys are rejected.
98	// encoding/json's struct decoding cannot do either: it matches tags
99	// case-insensitively and silently lets a later key overwrite an earlier one.
100	// Keys arrive already unescaped, so "id" collides with "id" while
101	// case variants like "ID" fall outside the whitelist.
102	func decodeRegisterRequest(body io.Reader) (registerRequest, bool) {
103		values, ok := decodeFields(body, registerFields)
104		if !ok {
105			return registerRequest{}, false
106		}
107		var payload registerRequest
108		for key, raw := range values {
109			var decodeErr error
110			switch key {
111			case "id":
112				decodeErr = json.Unmarshal(raw, &payload.ID)
113			case "severity":
114				decodeErr = json.Unmarshal(raw, &payload.Severity)
115			case "assets":
