133		decoder := json.NewDecoder(body)
134		token, err := decoder.Token()
135		if err != nil {
136			return nil, false
137		}
138		if delim, ok := token.(json.Delim); !ok || delim != '{' {
139			return nil, false
140		}
141		seen := map[string]bool{}
142		values := map[string]json.RawMessage{}
143		for decoder.More() {
144			token, err := decoder.Token()
145			if err != nil {
146				return nil, false
147			}
148			key, ok := token.(string)
149			if !ok || !allowed[key] || seen[key] {
150				return nil, false
151			}
152			seen[key] = true
153			var raw json.RawMessage
154			if err := decoder.Decode(&raw); err != nil {
155				return nil, false
156			}
157			values[key] = raw
158		}
159		if _, err := decoder.Token(); err != nil {
160			return nil, false
161		}
162		if err := decoder.Decode(&struct{}{}); err != io.EOF {
163			return nil, false
164		}
165		return values, true
166	}
