168	// valid reports whether every required field is present and well formed.
169	func (r *registerRequest) valid() bool {
170		if r.ID == nil || strings.TrimSpace(*r.ID) == "" {
171			return false
172		}
173		if r.Severity == nil || !validSeverities[*r.Severity] {
174			return false
175		}
176		if r.Owner == nil || strings.TrimSpace(*r.Owner) == "" {
177			return false
178		}
