314	// The owner is kept exactly as sent; only all-blank values are rejected.
315	func (r *transitionRequest) valid() bool {
316		if r.Stage == nil || !validStages[*r.Stage] {
317			return false
318		}
319		if r.Owner == nil || strings.TrimSpace(*r.Owner) == "" {
320			return false
321		}
322		return true
