325	func writeInvalidRequest(c *gin.Context) {
326		writeError(c, http.StatusBadRequest, "invalid_request", "request body must be a single JSON object with valid id, severity, assets, and owner")
327	}
328	
329	func writeInvalidQuery(c *gin.Context) {
330		writeError(c, http.StatusBadRequest, "invalid_query", "query parameters are missing, repeated, unknown, or hold invalid values")
331	}
