333	// writeError keeps the published error shape: a single top-level error object
334	// whose message never exposes SQL, stack traces, or file paths.
335	func writeError(c *gin.Context, status int, code, message string) {
336		c.JSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
