368	CREATE TABLE IF NOT EXISTS service_metadata (
369		key   TEXT PRIMARY KEY,
370		value TEXT NOT NULL
371	);
372	CREATE TABLE IF NOT EXISTS incidents (
373		id       TEXT PRIMARY KEY,
374		severity TEXT NOT NULL,
375		assets   TEXT NOT NULL,
376		stage    TEXT NOT NULL,
377		owner    TEXT NOT NULL
378	);
