380		incident_id TEXT NOT NULL REFERENCES incidents(id),
381		seq         INTEGER NOT NULL,
382		stage       TEXT NOT NULL,
383		owner       TEXT NOT NULL,
384		at          TEXT NOT NULL,
385		PRIMARY KEY (incident_id, seq)
386	);
387	`
