496			t.Fatalf("register: %v", err)
497		}
498	
499		// Readers hammer Get while the writer walks the incident through every
500		// stage. Each read must land entirely before or entirely after a commit:
501		// either the 受理/alice body with one entry, a later stage with its full
502		// history, but never a mixture of two states.
503		stop := make(chan struct{})
504		var wg sync.WaitGroup
505		for range 4 {
506			wg.Add(1)
507			go func() {
508				defer wg.Done()
509				for {
510					select {
511					case <-stop:
512						return
513					default:
514					}
515					incident, err := st.Get("INC-1")
516					if err != nil {
517						t.Errorf("get: %v", err)
518						return
519					}
520					checkConsistent(t, incident)
521				}
522			}()
523		}
524	
525		timestamps := make([]string, 0, len(stageFlow))
526		first, err := st.Get("INC-1")
527		if err != nil {
528			t.Fatalf("get: %v", err)
529		}
530		timestamps = append(timestamps, first.Timeline[0].At)
531		for i := 1; i < len(stageFlow); i++ {
532			moved, err := st.Transition("INC-1", stageFlow[i], ownerFlow[i])
533			if err != nil {
534				t.Fatalf("transition to %s: %v", stageFlow[i], err)
535			}
536			timestamps = append(timestamps, moved.Timeline[len(moved.Timeline)-1].At)
537		}
538		close(stop)
539		wg.Wait()
540	
541		// After the last transition returned, the stored record is the complete
542		// 关闭 state with every original timestamp preserved.
543		got, err := st.Get("INC-1")
544		if err != nil {
545			t.Fatalf("get: %v", err)
546		}
547		checkConsistent(t, got)
548		for i, entry := range got.Timeline {
549			if entry.At != timestamps[i] {
550				t.Fatalf("entry %d at = %q, want the original %q", i, entry.At, timestamps[i])
551			}
552		}
553	}
554	
555	func TestListConsistentWhileTransitionsCommit(t *testing.T) {
556		st, err := Open(filepath.Join(t.TempDir(), "store.db"))
557		if err != nil {
558			t.Fatalf("open: %v", err)
559		}
560		defer st.Close()
561	
562		// INC-1 and INC-2 share a severity and advance through the flow; INC-3
563		// stays in 受理 so the 受理 filter never goes empty.
564		for _, item := range []struct {
565			id       string
566			severity string
567		}{
568			{"INC-1", "high"},
569			{"INC-2", "high"},
570			{"INC-3", "low"},
571		} {
572			if _, err := st.Register(item.id, item.severity, ownerFlow[0], []string{"a"}); err != nil {
573				t.Fatalf("register %s: %v", item.id, err)
574			}
575		}
576	
577		filters := []struct {
578			severity string
579			stage    string
580		}{
581			{"", ""},
582			{"high", ""},
583			{"", "受理"},
584			{"high", "受理"},
585			{"high", "遏制"},
586			{"low", "受理"},
587		}
588	
589		stop := make(chan struct{})
590		var wg sync.WaitGroup
591		for range 4 {
592			wg.Add(1)
593			go func() {
594				defer wg.Done()
595				for {
596					select {
597					case <-stop:
598						return
599					default:
600					}
601					for _, filter := range filters {
602						incidents, err := st.List(filter.severity, filter.stage)
603						if err != nil {
604							t.Errorf("list %q/%q: %v", filter.severity, filter.stage, err)
605							return
606						}
607						for _, incident := range incidents {
608							// Every member matches the filter in the state its
609							// own body and history came from, and the combination
610							// of filters is an intersection.
611							if filter.severity != "" && incident.Severity != filter.severity {
612								t.Errorf("severity filter %q returned %+v", filter.severity, incident)
613							}
614							if filter.stage != "" && incident.Stage != filter.stage {
615								t.Errorf("stage filter %q returned %+v", filter.stage, incident)
616							}
617							checkConsistent(t, incident)
618						}
619					}
620				}
621			}()
622		}
623	
624		for _, id := range []string{"INC-1", "INC-2"} {
625			for i := 1; i < len(stageFlow); i++ {
626				if _, err := st.Transition(id, stageFlow[i], ownerFlow[i]); err != nil {
627					t.Fatalf("transition %s to %s: %v", id, stageFlow[i], err)
628				}
629			}
630		}
631		close(stop)
632		wg.Wait()
633	
634		// With no writes in flight, each filter reflects the final state.
635		final, err := st.List("high", "关闭")
636		if err != nil {
637			t.Fatalf("list: %v", err)
638		}
639		if len(final) != 2 || final[0].ID != "INC-1" || final[1].ID != "INC-2" {
640			t.Fatalf("final high/关闭 list = %+v", final)
641		}
642		for _, incident := range final {
643			checkConsistent(t, incident)
644		}
645		accepted, err := st.List("", "受理")
646		if err != nil {
647			t.Fatalf("list: %v", err)
648		}
649		if len(accepted) != 1 || accepted[0].ID != "INC-3" {
650			t.Fatalf("final 受理 list = %+v", accepted)
651		}
652		checkConsistent(t, accepted[0])
653	}
