701	func TestTransitionWalksThroughAllStages(t *testing.T) {
702		server, _ := newTestRouter(t)
703		registerIncident(t, server.URL, "INC-1", "high", "alice")
704	
705		stages := []string{"遏制", "清除", "恢复", "关闭"}
706		owners := []string{"alice", "bob", "  carol  ", "dave"}
707		for i, stage := range stages {
708			body := `{"stage":"` + stage + `","owner":"` + owners[i] + `"}`
709			status, incident := transition(t, server.URL, "INC-1", body)
710			if status != http.StatusOK {
711				t.Fatalf("to %s: status = %d, want 200 (%v)", stage, status, incident)
712			}
713			if incident["id"] != "INC-1" || incident["severity"] != "high" {
714				t.Fatalf("identity changed: %v", incident)
715			}
716			assets := incident["assets"].([]any)
717			if len(assets) != 1 || assets[0] != "a" {
718				t.Fatalf("assets changed: %v", assets)
719			}
720			if incident["stage"] != stage || incident["owner"] != owners[i] {
721				t.Fatalf("stage/owner = %v/%v, want %v/%v", incident["stage"], incident["owner"], stage, owners[i])
722			}
