741				t.Fatalf("from closed to %s: status = %d, want 409", stage, status)
742			}
743			if code := errorCode(t, body); code != "invalid_transition" {
744				t.Fatalf("code = %q, want invalid_transition", code)
745			}
746		}
747	}
