1040	// checkBodyConsistent fails the test unless a decoded incident body is
1041	// internally consistent: stage and owner match the last timeline entry and
1042	// the timeline walks the stage flow one entry at a time with the owners the
1043	// flow assigned. A body assembled from two committed states violates this.
1044	func checkBodyConsistent(t *testing.T, body map[string]any, stages, owners []string) {
1045		t.Helper()
