1070			}
1071			if entry["at"] == "" {
1072				t.Fatalf("timeline entry %d lost its timestamp: %v", i, body)
1073			}
1074		}
1075		last := timeline[len(timeline)-1].(map[string]any)
1076		if last["stage"] != body["stage"] || last["owner"] != body["owner"] {
1077			t.Fatalf("body %v/%v disagrees with last entry %v", body["stage"], body["owner"], last)
1078		}
