1081	func TestQueryConsistentWhileTransitionsCommit(t *testing.T) {
1082		server, _ := newTestRouter(t)
1083		stages := []string{"受理", "遏制", "清除", "恢复", "关闭"}
1084		owners := []string{"alice", "bob", "carol", "dave", "erin"}
1085	
1086		registerIncident(t, server.URL, "INC-1", "high", owners[0])
1087		registerIncident(t, server.URL, "INC-2", "high", owners[0])
1088		registerIncident(t, server.URL, "INC-3", "low", owners[0])
1089	
1090		// Concurrent readers query by id, by stage, and by the severity/stage
1091		// combination while the writer walks INC-1 and INC-2 through the flow.
1092		// Every 200 response must reflect one committed state: for INC-1 and
1093		// INC-2 either the pre-transition body with its shorter history or the
1094		// post-transition one, never a mixture.
1095		byID := map[string]bool{
1096			"/incidents?id=INC-1": true,
1097			"/incidents?id=INC-2": true,
1098		}
1099		stageAccepted := "/incidents?stage=" + url.QueryEscape("受理")
1100		combo := "/incidents?severity=high&stage=" + url.QueryEscape("遏制")
1101		queries := []string{
1102			"/incidents?id=INC-1",
1103			"/incidents?id=INC-2",
1104			"/incidents",
1105			stageAccepted,
1106			combo,
1107		}
1108		stop := make(chan struct{})
1109		var wg sync.WaitGroup
1110		for range 4 {
1111			wg.Add(1)
1112			go func() {
1113				defer wg.Done()
1114				for {
1115					select {
1116					case <-stop:
1117						return
1118					default:
1119					}
1120					for _, path := range queries {
1121						response, err := http.Get(server.URL + path)
1122						if err != nil {
1123							t.Errorf("get %s: %v", path, err)
1124							return
1125						}
1126						if response.StatusCode != http.StatusOK {
1127							response.Body.Close()
1128							t.Errorf("get %s: status %d", path, response.StatusCode)
1129							return
1130						}
1131						if byID[path] {
1132							var body map[string]any
1133							if err := json.NewDecoder(response.Body).Decode(&body); err != nil {
1134								t.Errorf("decode %s: %v", path, err)
1135								response.Body.Close()
1136								return
1137							}
1138							checkBodyConsistent(t, body, stages, owners)
1139						} else {
1140							var items []any
1141							if err := json.NewDecoder(response.Body).Decode(&items); err != nil {
1142								t.Errorf("decode %s: %v", path, err)
1143								response.Body.Close()
1144								return
1145							}
1146							for _, item := range items {
1147								body := item.(map[string]any)
1148								checkBodyConsistent(t, body, stages, owners)
1149								// Filter membership is decided in the same state
1150								// the body came from, and combined filters
1151								// intersect.
1152								if path == stageAccepted && body["stage"] != "受理" {
1153									t.Errorf("受理 filter returned %v", body)
1154								}
1155								if path == combo && (body["severity"] != "high" || body["stage"] != "遏制") {
1156									t.Errorf("combined filter returned %v", body)
1157								}
1158							}
1159						}
1160						response.Body.Close()
1161					}
1162				}
1163			}()
1164		}
1165	
1166		timestamps := map[string][]string{}
1167		for _, id := range []string{"INC-1", "INC-2"} {
1168			_, created := doRequest(t, http.MethodGet, server.URL+"/incidents?id="+id, "")
1169			timestamps[id] = []string{created["timeline"].([]any)[0].(map[string]any)["at"].(string)}
1170			for i := 1; i < len(stages); i++ {
1171				body := `{"stage":"` + stages[i] + `","owner":"` + owners[i] + `"}`
1172				status, moved := transition(t, server.URL, id, body)
1173				if status != http.StatusOK {
1174					t.Fatalf("transition %s to %s: status %d (%v)", id, stages[i], status, moved)
1175				}
1176				entry := moved["timeline"].([]any)[i].(map[string]any)
1177				timestamps[id] = append(timestamps[id], entry["at"].(string))
1178			}
1179		}
1180		close(stop)
1181		wg.Wait()
1182	
1183		// After every transition returned, queries show the final 关闭 state
1184		// with the complete history and the original timestamps untouched.
1185		for _, id := range []string{"INC-1", "INC-2"} {
1186			status, fetched := doRequest(t, http.MethodGet, server.URL+"/incidents?id="+id, "")
1187			if status != http.StatusOK {
1188				t.Fatalf("fetch %s: status %d", id, status)
1189			}
1190			checkBodyConsistent(t, fetched, stages, owners)
1191			timeline := fetched["timeline"].([]any)
1192			for i, item := range timeline {
1193				if at := item.(map[string]any)["at"]; at != timestamps[id][i] {
1194					t.Fatalf("%s entry %d at = %v, want the original %v", id, i, at, timestamps[id][i])
1195				}
1196			}
1197		}
1198	
1199		// The combined filter intersects on the final state: both high
1200		// incidents are closed, only INC-3 is still 受理.
1201		_, items := listIncidents(t, server.URL+"/incidents?severity=high&stage="+url.QueryEscape("关闭"))
1202		if len(items) != 2 || items[0].(map[string]any)["id"] != "INC-1" || items[1].(map[string]any)["id"] != "INC-2" {
1203			t.Fatalf("final high/关闭 list = %v", items)
1204		}
1205		_, items = listIncidents(t, server.URL+"/incidents?stage="+url.QueryEscape("受理"))
1206		if len(items) != 1 || items[0].(map[string]any)["id"] != "INC-3" {
1207			t.Fatalf("final 受理 list = %v", items)
1208		}
1209	}
